long parallel_sum(const std::vector<long>& v, unsigned threads) {
    std::vector<long> partial(threads, 0);
    std::vector<std::thread> pool;
    for (unsigned t = 0; t < threads; ++t) {
        pool.emplace_back([&v, &partial, t, threads] {
            const std::size_t begin = v.size() * t / threads;
            const std::size_t end = v.size() * (t + 1) / threads;
            long local = 0;
            for (std::size_t i = begin; i < end; ++i) local += v[i];
            partial[t] = local;
        });
    }
    for (std::thread& th : pool) th.join();
    return std::accumulate(partial.begin(), partial.end(), 0L);
}

