def finish_time(jobs, workers):
    free = [0] * workers
    for duration in jobs:
        i = free.index(min(free))
        free[i] += duration
    return max(free)

def rate(samples):
    if len(samples) < 2:
        return 0.0
    total = 0.0
    for i in range(1, len(samples)):
        before = samples[i - 1][1]
        now = samples[i][1]
        if now >= before:
            total += now - before
        else:
            total += now
    return total / (samples[-1][0] - samples[0][0])

def to_cumulative(edges, values):
    counts = []
    for edge in edges:
        counts.append(len([v for v in values if v <= edge]))
    return counts


def bucket_quantile(q, edges, counts):
    rank = q * counts[-1]
    lower_edge = 0.0
    lower_count = 0
    for edge, count in zip(edges, counts):
        if count >= rank:
            fraction = (rank - lower_count) / (count - lower_count)
            return lower_edge + fraction * (edge - lower_edge)
        lower_edge = edge
        lower_count = count
    return edges[-1]

def entry_points(text):
    found = {}
    inside = False
    for line in text.splitlines():
        line = line.strip()
        if line.startswith("["):
            inside = line == "[project.scripts]"
        elif inside and "=" in line:
            name, target = line.split("=", 1)
            module, function = target.strip().strip('"').split(":")
            found[name.strip()] = (module, function)
    return found

def find_defs(source):
    found = []
    number = 0
    for line in source.splitlines():
        number += 1
        words = line.strip().split(" ", 1)
        if len(words) == 2 and words[0] in ("def", "class"):
            name = words[1].split("(")[0].split(":")[0].strip()
            found.append((number, words[0], name))
    return found

