def hot_files(log, n):
    counts = {}
    for line in log.splitlines():
        path = line.strip()
        if path:
            counts[path] = counts.get(path, 0) + 1
    ranked = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    return [(count, path) for path, count in ranked[:n]]

def check_message(message):
    lines = message.splitlines()
    subject = lines[0] if lines else ""
    problems = []
    if len(subject) > 72:
        problems.append("subject too long")
    if subject.endswith("."):
        problems.append("subject ends with a full stop")
    if subject[:1].islower():
        problems.append("subject starts with a small letter")
    if len(lines) > 1 and lines[1].strip() != "":
        problems.append("no blank line after the subject")
    return problems
